DROP TABLE IF EXISTS puestos_votacion;
CREATE TABLE `puestos_votacion` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `departamento` varchar(100) NOT NULL,
  `municipio` varchar(100) NOT NULL,
  `cod_mpio` varchar(10) DEFAULT NULL,
  `puesto` varchar(255) NOT NULL,
  `comuna` varchar(100) DEFAULT NULL,
  `direccion` varchar(255) DEFAULT NULL,
  `latitud` decimal(10,8) DEFAULT NULL,
  `longitud` decimal(11,8) DEFAULT NULL,
  `estado` enum('Activo','Inactivo') DEFAULT 'Activo',
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_municipio` (`municipio`) USING BTREE,
  KEY `idx_departamento` (`departamento`) USING BTREE,
  KEY `idx_puesto` (`puesto`) USING BTREE,
  KEY `idx_cod_mpio` (`cod_mpio`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=1252 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;


DROP TABLE IF EXISTS supervisores_telefonos;
CREATE TABLE `supervisores_telefonos` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `telefono` varchar(20) NOT NULL,
  `nombre_supervisor` varchar(100) NOT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS usuarios_campanas;
CREATE TABLE `usuarios_campanas` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `usuario_id` int(11) NOT NULL,
  `campana_id` int(11) NOT NULL,
  `rol_campana` enum('administrador','coordinador','colaborador','veedor') NOT NULL DEFAULT 'colaborador',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_usuario_campana` (`usuario_id`,`campana_id`),
  KEY `idx_campana` (`campana_id`),
  CONSTRAINT `fk_uc_campana` FOREIGN KEY (`campana_id`) REFERENCES `campanas` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_uc_usuario` FOREIGN KEY (`usuario_id`) REFERENCES `usuarios` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS colaboradores;
CREATE TABLE `colaboradores` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `campana_id` int(11) NOT NULL,
  `nombres` varchar(100) NOT NULL,
  `apellidos` varchar(100) NOT NULL,
  `tipo_documento` enum('CC','TI','CE','PA','RC','NIT') DEFAULT 'CC',
  `documento` varchar(20) NOT NULL,
  `fecha_nacimiento` date NOT NULL,
  `genero` varchar(20) DEFAULT 'Otro',
  `perfil` varchar(100) DEFAULT 'Simpatizante',
  `nivel_liderazgo` int(11) DEFAULT 0,
  `nivel_participacion` enum('Simpatizante','Aportante','Activista de Opinion','Movilizador','Contradictor','Contratista') DEFAULT NULL,
  `areas_interes` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`areas_interes`)),
  `dato_potencial` int(11) DEFAULT 0,
  `dato_historico` int(11) DEFAULT 0,
  `estado` varchar(20) DEFAULT 'Nuevo',
  `revision` datetime DEFAULT NULL,
  `departamento` varchar(100) NOT NULL,
  `municipio` varchar(100) NOT NULL,
  `tipo_territorio` varchar(50) DEFAULT NULL,
  `territorio` varchar(100) DEFAULT NULL,
  `barrio` varchar(100) DEFAULT NULL,
  `territorio_id` int(11) DEFAULT NULL,
  `direccion` varchar(255) DEFAULT NULL,
  `detalle_ubicacion` text DEFAULT NULL,
  `lider_directo` varchar(20) DEFAULT NULL COMMENT 'Documento del lider',
  `email` varchar(255) NOT NULL,
  `telefono` varchar(20) NOT NULL,
  `telefono_whatsapp` varchar(20) NOT NULL,
  `observaciones` text DEFAULT NULL,
  `usuario_registro_id` int(11) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `puesto_votacion` varchar(255) DEFAULT NULL COMMENT 'Nombre del puesto de votacion',
  `mesa_votacion` varchar(10) DEFAULT NULL COMMENT 'Numero de mesa',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_doc_camp` (`documento`,`campana_id`),
  KEY `idx_campana` (`campana_id`),
  KEY `idx_perfil` (`perfil`),
  KEY `idx_lider` (`lider_directo`),
  KEY `idx_territorio` (`departamento`,`municipio`),
  KEY `idx_jerarquia` (`campana_id`,`lider_directo`,`documento`),
  KEY `idx_territorio_campana` (`campana_id`,`departamento`,`municipio`),
  KEY `idx_puesto_mesa` (`campana_id`,`puesto_votacion`,`mesa_votacion`)
) ENGINE=InnoDB AUTO_INCREMENT=1847 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS curriculum;
CREATE TABLE `curriculum` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `colaborador_id` int(11) NOT NULL,
  `experiencia_laboral` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Array de objetos: [{cargo, empresa, fecha_inicio, fecha_fin, descripcion}]' CHECK (json_valid(`experiencia_laboral`)),
  `formacion_academica` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Array de objetos: [{titulo, institucion, fecha_inicio, fecha_fin, nivel}]' CHECK (json_valid(`formacion_academica`)),
  `participacion_politica` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Array de objetos: [{cargo, organizacion, fecha_inicio, fecha_fin, descripcion}]' CHECK (json_valid(`participacion_politica`)),
  `resumen_profesional` text DEFAULT NULL,
  `habilidades` text DEFAULT NULL,
  `idiomas` varchar(255) DEFAULT NULL,
  `reconocimientos` text DEFAULT NULL,
  `referencias` text DEFAULT NULL,
  `observaciones` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_colaborador` (`colaborador_id`),
  CONSTRAINT `curriculum_ibfk_1` FOREIGN KEY (`colaborador_id`) REFERENCES `colaboradores` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=232 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS historial_estados;
CREATE TABLE `historial_estados` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `colaborador_id` int(11) NOT NULL,
  `campana_id` int(11) NOT NULL,
  `dato_potencial_anterior` int(11) DEFAULT NULL,
  `dato_potencial_nuevo` int(11) DEFAULT NULL,
  `dato_historico_anterior` int(11) DEFAULT NULL,
  `dato_historico_nuevo` int(11) DEFAULT NULL,
  `estado_anterior` varchar(20) DEFAULT NULL,
  `estado_nuevo` varchar(20) DEFAULT NULL,
  `motivo` text DEFAULT NULL COMMENT 'Razon del cambio o reevaluacion',
  `tipo_cambio` enum('creacion','actualizacion','reevaluacion') DEFAULT 'actualizacion',
  `usuario_id` int(11) NOT NULL COMMENT 'Usuario que realizo el cambio',
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `usuario_id` (`usuario_id`),
  KEY `idx_colaborador` (`colaborador_id`),
  KEY `idx_campana` (`campana_id`),
  KEY `idx_fecha` (`created_at`),
  KEY `idx_tipo` (`tipo_cambio`),
  CONSTRAINT `historial_estados_ibfk_1` FOREIGN KEY (`colaborador_id`) REFERENCES `colaboradores` (`id`) ON DELETE CASCADE,
  CONSTRAINT `historial_estados_ibfk_2` FOREIGN KEY (`campana_id`) REFERENCES `campanas` (`id`),
  CONSTRAINT `historial_estados_ibfk_3` FOREIGN KEY (`usuario_id`) REFERENCES `usuarios` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=44 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS reportes_diaD;
CREATE TABLE `reportes_diaD` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `id_campaña` varchar(20) DEFAULT '02',
  `id_colaborador` int(11) NOT NULL,
  `id_puesto` int(11) DEFAULT NULL,
  `id_mesa` int(11) DEFAULT NULL,
  `votos_nuevos` int(11) NOT NULL,
  `votos_total` int(11) NOT NULL,
  `timestamp` timestamp NULL DEFAULT current_timestamp(),
  `certificado_url` varchar(255) DEFAULT NULL,
  `estado_semaforo` varchar(20) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_reportes_colaborador` (`id_colaborador`),
  CONSTRAINT `fk_reportes_colaborador` FOREIGN KEY (`id_colaborador`) REFERENCES `colaboradores` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1308 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS sesiones;
CREATE TABLE `sesiones` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `usuario_id` int(11) NOT NULL,
  `token` varchar(255) NOT NULL,
  `ip_address` varchar(45) DEFAULT NULL,
  `user_agent` varchar(500) DEFAULT NULL,
  `ultima_actividad` datetime DEFAULT NULL,
  `expires_at` datetime NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `token` (`token`),
  KEY `idx_usuario` (`usuario_id`),
  KEY `idx_expires` (`expires_at`),
  CONSTRAINT `fk_sesion_usuario` FOREIGN KEY (`usuario_id`) REFERENCES `usuarios` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=400 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS v_colaboradores_completo;
CREATE VIEW v_colaboradores_completo AS CREATE ALGORITHM=UNDEFINED DEFINER=`u156469157_aratio_v1`@`%` SQL SECURITY DEFINER VIEW `v_colaboradores_completo` AS select `c`.`id` AS `id`,`c`.`campana_id` AS `campana_id`,`c`.`nombres` AS `nombres`,`c`.`apellidos` AS `apellidos`,`c`.`tipo_documento` AS `tipo_documento`,`c`.`documento` AS `documento`,`c`.`fecha_nacimiento` AS `fecha_nacimiento`,`c`.`genero` AS `genero`,`c`.`perfil` AS `perfil`,`c`.`nivel_liderazgo` AS `nivel_liderazgo`,`c`.`nivel_participacion` AS `nivel_participacion`,`c`.`areas_interes` AS `areas_interes`,`c`.`dato_potencial` AS `dato_potencial`,`c`.`dato_historico` AS `dato_historico`,`c`.`estado` AS `estado`,`c`.`revision` AS `revision`,`c`.`departamento` AS `departamento`,`c`.`municipio` AS `municipio`,`c`.`tipo_territorio` AS `tipo_territorio`,`c`.`territorio` AS `territorio`,`c`.`barrio` AS `barrio`,`c`.`direccion` AS `direccion`,`c`.`detalle_ubicacion` AS `detalle_ubicacion`,`c`.`lider_directo` AS `lider_directo`,`c`.`email` AS `email`,`c`.`telefono` AS `telefono`,`c`.`telefono_whatsapp` AS `telefono_whatsapp`,`c`.`observaciones` AS `observaciones`,`c`.`usuario_registro_id` AS `usuario_registro_id`,`c`.`created_at` AS `created_at`,`c`.`updated_at` AS `updated_at`,`c`.`puesto_votacion` AS `puesto_votacion`,`c`.`mesa_votacion` AS `mesa_votacion`,concat(`c`.`nombres`,' ',`c`.`apellidos`) AS `nombre_completo`,timestampdiff(YEAR,`c`.`fecha_nacimiento`,curdate()) AS `edad`,concat(`l`.`nombres`,' ',`l`.`apellidos`) AS `nombre_lider`,`l`.`documento` AS `documento_lider_completo`,count(distinct `s`.`id`) AS `total_seguidores` from ((`colaboradores` `c` left join `colaboradores` `l` on(`c`.`lider_directo` = `l`.`documento`)) left join `colaboradores` `s` on(`s`.`lider_directo` = `c`.`documento`)) group by `c`.`id`


DROP TABLE IF EXISTS v_colaboradores_red;
CREATE VIEW v_colaboradores_red AS CREATE ALGORITHM=UNDEFINED DEFINER=`u156469157_aratio_v1`@`%` SQL SECURITY DEFINER VIEW `v_colaboradores_red` AS select `c`.`id` AS `id`,`c`.`documento` AS `documento`,`c`.`nombres` AS `nombres`,`c`.`apellidos` AS `apellidos`,`c`.`perfil` AS `perfil`,`c`.`nivel_participacion` AS `nivel_participacion`,`c`.`estado` AS `estado`,`c`.`dato_potencial` AS `dato_potencial`,`c`.`dato_historico` AS `dato_historico`,`c`.`lider_directo` AS `lider_directo`,`c`.`campana_id` AS `campana_id`,`c`.`departamento` AS `departamento`,`c`.`municipio` AS `municipio`,`c`.`tipo_territorio` AS `tipo_territorio`,`c`.`territorio` AS `territorio`,`c`.`barrio` AS `barrio`,`c`.`email` AS `email`,`c`.`telefono` AS `telefono`,`c`.`created_at` AS `created_at`,(select count(0) from `colaboradores` `s` where `s`.`lider_directo` = `c`.`documento` and `s`.`campana_id` = `c`.`campana_id`) AS `total_seguidores`,`l`.`nombres` AS `lider_nombres`,`l`.`apellidos` AS `lider_apellidos`,`l`.`perfil` AS `lider_perfil`,`l`.`id` AS `lider_id` from (`colaboradores` `c` left join `colaboradores` `l` on(`c`.`lider_directo` = `l`.`documento` and `c`.`campana_id` = `l`.`campana_id`))


DROP TABLE IF EXISTS v_estadisticas_campana;
CREATE VIEW v_estadisticas_campana AS CREATE ALGORITHM=UNDEFINED DEFINER=`u156469157_aratio_v1`@`%` SQL SECURITY DEFINER VIEW `v_estadisticas_campana` AS select `colaboradores`.`campana_id` AS `campana_id`,count(0) AS `total_colaboradores`,count(distinct `colaboradores`.`lider_directo`) AS `total_lideres_unicos`,sum(case when `colaboradores`.`lider_directo` is null or `colaboradores`.`lider_directo` = '' then 1 else 0 end) AS `sin_lider`,sum(case when `colaboradores`.`perfil` like '%Lider%' then 1 else 0 end) AS `total_lideres`,count(distinct `colaboradores`.`municipio`) AS `municipios`,count(distinct `colaboradores`.`departamento`) AS `departamentos`,count(distinct `colaboradores`.`territorio`) AS `territorios`,count(distinct `colaboradores`.`barrio`) AS `barrios`,sum(case when `colaboradores`.`estado` = 'Nuevo' then 1 else 0 end) AS `nuevos`,sum(case when `colaboradores`.`estado` = 'Crecio' then 1 else 0 end) AS `crecieron`,sum(case when `colaboradores`.`estado` = 'Igual' then 1 else 0 end) AS `igual`,sum(case when `colaboradores`.`estado` = 'Decrecio' then 1 else 0 end) AS `decrecieron`,avg(`colaboradores`.`dato_potencial`) AS `promedio_potencial`,avg(`colaboradores`.`dato_historico`) AS `promedio_historico` from `colaboradores` group by `colaboradores`.`campana_id`


DROP TABLE IF EXISTS v_estadisticas_perfil;
CREATE VIEW v_estadisticas_perfil AS CREATE ALGORITHM=UNDEFINED DEFINER=`u156469157_aratio_v1`@`%` SQL SECURITY DEFINER VIEW `v_estadisticas_perfil` AS select `colaboradores`.`perfil` AS `perfil`,count(0) AS `total`,count(case when `colaboradores`.`estado` = 'Creció' then 1 end) AS `crecio`,count(case when `colaboradores`.`estado` = 'Decrece' then 1 end) AS `decrece`,count(case when `colaboradores`.`estado` = 'Nuevo' then 1 end) AS `nuevos`,avg(`colaboradores`.`dato_potencial`) AS `promedio_potencial` from `colaboradores` group by `colaboradores`.`perfil`


DROP TABLE IF EXISTS v_estadisticas_territorio;
CREATE VIEW v_estadisticas_territorio AS CREATE ALGORITHM=UNDEFINED DEFINER=`u156469157_aratio_v1`@`%` SQL SECURITY DEFINER VIEW `v_estadisticas_territorio` AS select `colaboradores`.`territorio` AS `territorio`,`colaboradores`.`tipo_territorio` AS `tipo_territorio`,count(0) AS `total_colaboradores`,count(distinct `colaboradores`.`lider_directo`) AS `total_lideres`,avg(`colaboradores`.`dato_potencial`) AS `promedio_potencial` from `colaboradores` where `colaboradores`.`territorio` is not null group by `colaboradores`.`territorio`,`colaboradores`.`tipo_territorio`


DROP TABLE IF EXISTS v_lideres_metricas;
CREATE VIEW v_lideres_metricas AS CREATE ALGORITHM=UNDEFINED DEFINER=`u156469157_aratio_v1`@`%` SQL SECURITY DEFINER VIEW `v_lideres_metricas` AS select `c`.`id` AS `id`,`c`.`documento` AS `documento`,concat(`c`.`nombres`,' ',`c`.`apellidos`) AS `nombre_completo`,`c`.`perfil` AS `perfil`,`c`.`territorio` AS `territorio`,count(distinct `s`.`id`) AS `total_seguidores_directos`,avg(`s`.`dato_potencial`) AS `promedio_potencial_seguidores`,sum(case when `s`.`estado` = 'Creció' then 1 else 0 end) AS `seguidores_creciendo` from (`colaboradores` `c` left join `colaboradores` `s` on(`s`.`lider_directo` = `c`.`documento`)) group by `c`.`id`,`c`.`documento`,`c`.`nombres`,`c`.`apellidos`,`c`.`perfil`,`c`.`territorio` having `total_seguidores_directos` > 0 order by count(distinct `s`.`id`) desc

